13	  const parsed: unknown = JSON.parse(text);
14	  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
15	    throw new Error('Expected a database command result object.');
16	  }
17	  const message = Reflect.get(parsed, 'message');
18	  const actionableStderr = Reflect.get(parsed, 'actionableStderr');
19	  const actionableStdout = Reflect.get(parsed, 'actionableStdout');
20	  if (
21	    typeof message !== 'string' || !Array.isArray(actionableStderr) ||
22	    !actionableStderr.every((line) => typeof line === 'string') ||
23	    !Array.isArray(actionableStdout) ||
24	    !actionableStdout.every((line) => typeof line === 'string')
25	  ) {
26	    throw new Error('Expected bounded database command diagnostic streams.');
27	  }
28	  return { message, actionableStderr, actionableStdout };
29	}
