32	  const diagnostics = [...result.actionableStderr, ...result.actionableStdout];
33	  const messageIndex = diagnostics.indexOf(result.message);
34	  return [result.message, ...diagnostics.filter((_, index) => index !== messageIndex)].join(' | ');
