    stdoutBuffer += '\n';
    captureActionableStdoutLines(true);
  })();

  const timeoutId = options.timeoutSeconds === undefined ? undefined : setTimeout(() => {
    try {
      child.kill('SIGTERM');
      timedOut = true;
    } catch {
