      'run',
      '--allow-run',
      '--allow-write',
      runnerPath,
      errorFile,
      `db:${dbTaskOperation(operation)}:${target.taskSuffix}`,
      String(timeoutSeconds),
    ],
    {
      cwd: target.workdir,
      env: {
        ...process.env,
