{
  const root = await Deno.makeTempDir({ prefix: 'eval-d235-utf8-' });
  try {
    const runner = `${root}/run-tool.mts`;
    await Deno.writeTextFile(runner, await Deno.readTextFile(templateNew));
    // Adversarial: truncation boundaries land mid-character by construction (255-byte budget vs 3-byte chars).
    const emoji = '𝕏'; // 4-byte UTF-8 surrogate pair
    const cjk = '斜'; // 3-byte
    const lines = Array.from(
      { length: 64 },
      (_, i) =>
        `${i % 2 === 0 ? 'stderr' : 'stdout'} ${i}: ${emoji}${cjk.repeat(300)}𝕏 tail-${i} 斜`,
    );
    await Deno.writeTextFile(
      `${root}/flood.ts`,
      `const e=new TextEncoder();await Deno.stderr.write(e.encode(${
        JSON.stringify(lines.filter((_, i) => i % 2 === 0).join('\n') + '\n')
      }));await Deno.stdout.write(e.encode(${
        JSON.stringify(lines.filter((_, i) => i % 2 === 1).join('\n') + '\n')
      }));Deno.exit(16);`,
    );
    await Deno.writeTextFile(
      `${root}/deno.json`,
      JSON.stringify({ tasks: { 'db:seed:eval': 'deno run --allow-all flood.ts' } }),
    );
