    const resultPath = `${root}/res.json`;
    const errorPath = `${root}/e.error`;
    await Deno.writeTextFile(
      reqPath,
      JSON.stringify({ NETSCRIPT_PRISMA_OPERATION: 'seed', NETSCRIPT_DB_RESULT_FILE: resultPath }),
    );
    await new Deno.Command(Deno.execPath(), {
      args: ['run', '--allow-all', runner, '--request', reqPath, 'eval'],
      cwd: root,
      stdout: 'piped',
      stderr: 'piped',
    }).output();
    await new Deno.Command(Deno.execPath(), {
      args: ['run', '--allow-all', runner, errorPath, 'db:seed:eval'],
      cwd: root,
      stdout: 'piped',
      stderr: 'piped',
    }).output();
    const result = parseDiag(await Deno.readTextFile(resultPath));
    const allLines = [...result.actionableStderr, ...result.actionableStdout];
    const bad = allLines.filter((l) => l.includes('�'));
    const overBudget = allLines.filter((l) => bytes(l) > 255);
    // Re-decode the raw error file: split characters survive a byte-level round trip only if unsplit.
    const rawError = await Deno.readTextFile(errorPath);
    const rawLines = rawError.split('\n').filter((l) => l.length > 0);
    const rawBad = rawLines.filter((l) => l.includes('�'));
    const utf8Only = /[-￿]/.test(rawError);
    console.log(`\n== UTF-8 INTEGRITY (new, 4-byte + 3-byte chars, 64 lines)`);
    console.log(
      `   retained lines=${allLines.length}, replacement chars in retained=${bad.length}, lines>255B=${overBudget.length}, replacement chars in error file=${rawBad.length}, error file bytes=${bytes(rawError)}, error file lines=${rawLines.length}`,
    );
    console.log(`   sample truncated line: ${JSON.stringify(allLines[0].slice(0, 100))}`);
    console.log(`   emoji survived head: ${JSON.stringify(allLines[0].slice(0, 3))}`);
  } finally {
    await Deno.remove(root, { recursive: true });
  }
}

