// IMPL-EVAL measurement harness for D-235 shared diagnostic budget. Scratch, read-only w.r.t. repo.
const encoder = new TextEncoder();
const bytes = (s: string) => encoder.encode(s).byteLength;

interface Diag {
  message: string;
  actionableStderr: string[];
  actionableStdout: string[];
}
function parseDiag(text: string): Diag {
  const p: unknown = JSON.parse(text);
  const o = p as Record<string, unknown>;
  return {
    message: o.message as string,
    actionableStderr: o.actionableStderr as string[],
    actionableStdout: o.actionableStdout as string[],
  };
}
const flatten = (r: Diag) => {
  const d = [...r.actionableStderr, ...r.actionableStdout];
  const i = d.indexOf(r.message);
  return [r.message, ...d.filter((_, k) => k !== i)].join(' | ');
};

async function runScenario(
  label: string,
  templatePath: string,
  stderrLines: string[],
  stdoutLines: string[],
  opts: { requestMode?: boolean; expectMessageShape?: RegExp } = {},
): Promise<void> {
  const root = await Deno.makeTempDir({ prefix: 'eval-d235-' });
  try {
    const runner = `${root}/run-tool.mts`;
    const template = await Deno.readTextFile(templatePath);
    const childSrc =
      `const e=new TextEncoder();${
        stderrLines.length
          ? `await Deno.stderr.write(e.encode(${JSON.stringify(stderrLines.join('\n') + '\n')}));`
          : ''
      }${
        stdoutLines.length
          ? `await Deno.stdout.write(e.encode(${JSON.stringify(stdoutLines.join('\n') + '\n')}));`
          : ''
      }Deno.exit(16);`;
    await Deno.writeTextFile(runner, template);
    await Deno.writeTextFile(`${root}/flood.ts`, childSrc);
    await Deno.writeTextFile(
      `${root}/deno.json`,
      JSON.stringify({ tasks: { 'db:seed:eval': 'deno run --allow-all flood.ts' } }),
    );
    const errorPath = `${root}/eval.error`;
    const resultPath = `${root}/eval.result.json`;
    let code: number;
    if (opts.requestMode) {
      const reqPath = `${root}/eval.request.json`;
      await Deno.writeTextFile(
        reqPath,
        JSON.stringify({ NETSCRIPT_PRISMA_OPERATION: 'seed', NETSCRIPT_DB_RESULT_FILE: resultPath }),
      );
      const out = await new Deno.Command(Deno.execPath(), {
        args: ['run', '--allow-all', runner, '--request', reqPath, 'eval'],
        cwd: root,
        stdout: 'piped',
        stderr: 'piped',
      }).output();
      code = out.code;
      if (code !== 16) {
        console.log('   [debug] runner stderr:', new TextDecoder().decode(out.stderr).slice(0, 400));
      }
    } else {
      const out = await new Deno.Command(Deno.execPath(), {
        args: ['run', '--allow-all', runner, errorPath, 'db:seed:eval'],
        cwd: root,
        stdout: 'piped',
        stderr: 'piped',
      }).output();
      code = out.code;
    }
    const errorText = await Deno.readTextFile(errorPath).catch(() => '(no error file)');
    const resultText = await Deno.readTextFile(resultPath).catch(() => null);
    const result = resultText ? parseDiag(resultText) : null;
    const flattened = result ? flatten(result) : null;
    console.log(`\n== ${label} (exit=${code}, template=${templatePath.split('/').pop()})`);
    console.log(
      `   error file:      ${bytes(errorText)} B  (${(await Deno.stat(errorPath).catch(() => null))?.size ?? '?'} B on disk), lines=${errorText ? errorText.split('\n').length - (errorText.endsWith('\n') ? 1 : 0) : 0}`,
    );
    if (result) {
      console.log(
        `   result record:   ${bytes(resultText!)} B  (stderr=${result.actionableStderr.length} lines, stdout=${result.actionableStdout.length} lines)`,
      );
      console.log(
        `   flattened msg:   ${bytes(flattened!)} B  (message=${bytes(result.message)} B)`,
      );
      console.log(`   message: ${JSON.stringify(result.message.slice(0, 160))}`);
      if (opts.expectMessageShape) {
        console.log(
          `   message matches failure shape: ${opts.expectMessageShape.test(result.message)}`,
        );
      }
    } else {
      console.log(`   result record:   (none — direct mode)`);
    }
  } finally {
    await Deno.remove(root, { recursive: true });
  }
}

