deno eval '
const root = await Deno.makeTempDir({prefix:"eval-d235-deg-"});
const template = await Deno.readTextFile("/home/agent/projects/netscript/worktrees/007-s8-impleval/.llm/tmp/eval-d235/run-tool.new.mts");
await Deno.writeTextFile(root+"/run-tool.mts", template);
const stderrLines = Array.from({length:32},(_,i)=>`stderr ${i+1}: `+"s".repeat(1000));
await Deno.writeTextFile(root+"/flood.ts", `const e=new TextEncoder();await Deno.stderr.write(e.encode(${JSON.stringify(stderrLines.join("\n")+"\n")}));await Deno.stdout.write(e.encode(new TextEncoder().encode("Error: connection refused to database host db.internal:5432\n")));Deno.exit(16);`);
await Deno.writeTextFile(root+"/deno.json", JSON.stringify({tasks:{"db:seed:eval":"deno run --allow-all flood.ts"}}));
await new Deno.Command(Deno.execPath(),{args:["run","--allow-all",root+"/run-tool.mts",root+"/e.error","db:seed:eval"],cwd:root,stdout:"piped",stderr:"piped"}).output();
const err = await Deno.readTextFile(root+"/e.error");
const lines = err.split("\n").filter(l=>l.length);
console.log("lines:", lines.length, "| real stdout error present:", lines.some(l=>l.includes("connection refused")), "| at index", lines.findIndex(l=>l.includes("connection refused")));
console.log("stderr head lines retained:", lines.slice(0,8).every(l=>l.startsWith("stderr")), "| last line:", JSON.stringify(lines[lines.length-1].slice(0,60)));
await Deno.remove(root,{recursive:true});
'

deno eval '
const root = await Deno.makeTempDir({prefix:"eval-d235-deg2-"});
const template = await Deno.readTextFile("/home/agent/projects/netscript/worktrees/007-s8-impleval/.llm/tmp/eval-d235/run-tool.new.mts");
await Deno.writeTextFile(root+"/run-tool.mts", template);
const stderrLines = Array.from({length:32},(_,i)=>`stderr ${i+1}: `+"s".repeat(1000));
const realError = "Error: connection refused to database host db.internal:5432";
await Deno.writeTextFile(root+"/flood.ts", `const e=new TextEncoder();await Deno.stderr.write(e.encode(${JSON.stringify(stderrLines.join("\n")+"\n")}));await Deno.stdout.write(e.encode(${JSON.stringify(realError+"\n")}));Deno.exit(16);`);
await Deno.writeTextFile(root+"/deno.json", JSON.stringify({tasks:{"db:seed:eval":"deno run --allow-all flood.ts"}}));
const out = await new Deno.Command(Deno.execPath(),{args:["run","--allow-all",root+"/run-tool.mts",root+"/e.error","db:seed:eval"],cwd:root,stdout:"piped",stderr:"piped"}).output();
const err = await Deno.readTextFile(root+"/e.error");
const lines = err.split("\n").filter(l=>l.length);
const idx = lines.findIndex(l=>l.includes("connection refused"));
console.log("exit:", out.code, "| lines:", lines.length, "| real stdout error present:", idx>=0, "| index:", idx, "| bytes:", new TextEncoder().encode(err).byteLength);
console.log("first 8 stderr-flood:", lines.slice(0,8).filter(l=>l.startsWith("stderr")).length, "| tail stderr lines:", lines.slice(8).filter(l=>l.startsWith("stderr")).length);
await Deno.remove(root,{recursive:true});
'

